package com.decod.grm;

import org.json.JSONArray;
import org.json.JSONObject;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

final class CloudClient {
    static final String BASE="https://headless-ewridufbfjc-decodlabel-140a.wix-site-host.com"; private final GrmStore store;
    CloudClient(GrmStore store){this.store=store;}
    synchronized void sync()throws Exception{if(!store.isLicensed())throw new IllegalStateException("G-Rm lisansı doğrulanamadı");store.seedAllIfNeeded();JSONObject s=store.settings();if(!s.optBoolean("cloudRegistered",false)){JSONObject body=new JSONObject().put("deviceName",android.os.Build.MANUFACTURER+" "+android.os.Build.MODEL).put("platform","android").put("appVersion","22.0.0-mobile.1");JSONObject r=request("POST","/api/device/register",body);if(!r.optBoolean("ok",false)||!r.optBoolean("registered",false)||r.optBoolean("revoked",false))throw new IllegalStateException("G-Cloud cihaz kaydı tamamlanamadı");store.markCloudRegistered();}for(int batch=0;batch<5;batch++){JSONArray box=store.outbox();if(box.length()==0)break;JSONArray ops=new JSONArray();int max=Math.min(100,box.length());for(int i=0;i<max;i++)ops.put(box.getJSONObject(i));JSONObject r=request("POST","/api/sync/push",new JSONObject().put("ops",ops));JSONArray failed=r.optJSONArray("failedOpIds");if(failed!=null&&failed.length()>0)throw new IllegalStateException("G-Cloud "+failed.length()+" işlemi kabul etmedi");Set<String> acked=new HashSet<>();for(String k:new String[]{"acceptedOpIds","duplicateOpIds"}){JSONArray a=r.optJSONArray(k);if(a!=null)for(int i=0;i<a.length();i++)acked.add(a.optString(i));}store.removeOutboxIds(acked);if(acked.isEmpty())break;}for(int page=0;page<5;page++){JSONObject c=store.cursor();String path="/api/sync/pull?limit=100";if(c!=null&&!JsonUtil.s(c,"createdAt").isEmpty()&&!JsonUtil.s(c,"itemId").isEmpty())path+="&after="+enc(JsonUtil.s(c,"createdAt"))+"&afterId="+enc(JsonUtil.s(c,"itemId"));JSONObject r=request("GET",path,null);JSONArray ops=r.optJSONArray("operations");JSONObject next=r.optJSONObject("nextCursor");if(ops==null||ops.length()==0||next==null)break;for(int i=0;i<ops.length();i++)store.applyRemote(ops.getJSONObject(i));store.setCursor(next);request("POST","/api/sync/ack",new JSONObject().put("cursor",next));if(ops.length()<100)break;}store.setSyncStatus("G-Cloud eşitlendi",true);}
    private JSONObject request(String method,String path,JSONObject body)throws Exception{JSONObject s=store.settings();String token=JsonUtil.s(s,"cloudToken"),device=JsonUtil.s(s,"deviceId"),wk=JsonUtil.s(s,"workspaceKey");if(token.isEmpty())throw new IllegalStateException("G-Cloud lisansı bulunamadı");byte[] payload=body==null?new byte[0]:body.toString().getBytes(StandardCharsets.UTF_8);Exception last=null;for(int attempt=0;attempt<5;attempt++){long ts=System.currentTimeMillis();String canonical=method.toUpperCase(Locale.ROOT)+"\n"+path+"\n"+ts+"\n"+device+"\n"+CryptoBox.b64u(CryptoBox.sha256(payload));String sig=CryptoBox.b64u(CryptoBox.hmacSha256(CryptoBox.tenantKey(wk),canonical.getBytes(StandardCharsets.UTF_8)));HttpURLConnection c=(HttpURLConnection)new URL(BASE+path).openConnection();c.setRequestMethod(method);c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setRequestProperty("X-GRM-License",token);c.setRequestProperty("X-GRM-Device-Id",device);c.setRequestProperty("X-GRM-Timestamp",String.valueOf(ts));c.setRequestProperty("X-GRM-Signature",sig);c.setRequestProperty("Accept","application/json");if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.getOutputStream().write(payload);}int code=c.getResponseCode();InputStream in=code>=200&&code<300?c.getInputStream():c.getErrorStream();String text=read(in);c.disconnect();if(code>=200&&code<300)return text.trim().isEmpty()?new JSONObject():new JSONObject(text);last=new IllegalStateException("G-Cloud HTTP "+code+": "+text);if((code==429||code==502||code==503||code==504)&&attempt<4){Thread.sleep(code==429?5000:Math.min(15000,1000L<<attempt));continue;}throw last;}throw last==null?new IllegalStateException("G-Cloud isteği başarısız"):last;}
    private static String read(InputStream in)throws Exception{if(in==null)return"";try(in;ByteArrayOutputStream o=new ByteArrayOutputStream()){byte[]b=new byte[8192];int r;while((r=in.read(b))>0)o.write(b,0,r);return o.toString(StandardCharsets.UTF_8);}}
    private static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8");}
}